BEGIN;
CREATE OR REPLACE FUNCTION asset_journal_reject_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'asset conservation journal history is immutable'; END $$;
CREATE TABLE IF NOT EXISTS journal_asset_units (unit_hash text PRIMARY KEY CHECK(unit_hash ~ '^[a-f0-9]{64}$'),scope_hash text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS journal_accounts (account_hash text PRIMARY KEY CHECK(account_hash ~ '^[a-f0-9]{64}$'),scope_hash text NOT NULL,unit_hash text NOT NULL REFERENCES journal_asset_units(unit_hash),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS journal_source_events (event_hash text PRIMARY KEY CHECK(event_hash ~ '^[a-f0-9]{64}$'),scope_hash text NOT NULL,source_owner text NOT NULL,source_stream text NOT NULL,event_id text NOT NULL,revision text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(scope_hash,source_owner,source_stream,event_id,revision));
CREATE TABLE IF NOT EXISTS journal_input_manifests (manifest_hash text PRIMARY KEY CHECK(manifest_hash ~ '^[a-f0-9]{64}$'),scope_hash text NOT NULL,idempotency_key text NOT NULL,request_hash text NOT NULL CHECK(request_hash ~ '^[a-f0-9]{64}$'),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(scope_hash,idempotency_key));
CREATE TABLE IF NOT EXISTS journal_transaction_attempts (attempt_hash text PRIMARY KEY CHECK(attempt_hash ~ '^[a-f0-9]{64}$'),scope_hash text NOT NULL,manifest_hash text NOT NULL REFERENCES journal_input_manifests(manifest_hash),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS journal_transactions (transaction_hash text PRIMARY KEY CHECK(transaction_hash ~ '^[a-f0-9]{64}$'),scope_hash text NOT NULL,manifest_hash text NOT NULL REFERENCES journal_input_manifests(manifest_hash),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS journal_postings (posting_hash text PRIMARY KEY CHECK(posting_hash ~ '^[a-f0-9]{64}$'),transaction_hash text NOT NULL REFERENCES journal_transactions(transaction_hash),ordinal bigint NOT NULL CHECK(ordinal > 0),account_hash text NOT NULL REFERENCES journal_accounts(account_hash),unit_hash text NOT NULL REFERENCES journal_asset_units(unit_hash),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(transaction_hash,ordinal));
CREATE TABLE IF NOT EXISTS journal_lifecycle_events (event_hash text PRIMARY KEY CHECK(event_hash ~ '^[a-f0-9]{64}$'),transaction_hash text NOT NULL REFERENCES journal_transactions(transaction_hash),sequence bigint NOT NULL CHECK(sequence > 0),predecessor_hash text,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(transaction_hash,sequence));
CREATE TABLE IF NOT EXISTS journal_settlement_links (link_hash text PRIMARY KEY CHECK(link_hash ~ '^[a-f0-9]{64}$'),scope_hash text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS journal_correction_links (link_hash text PRIMARY KEY CHECK(link_hash ~ '^[a-f0-9]{64}$'),scope_hash text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS journal_conservation_checks (check_hash text PRIMARY KEY CHECK(check_hash ~ '^[a-f0-9]{64}$'),scope_hash text NOT NULL,manifest_hash text NOT NULL REFERENCES journal_input_manifests(manifest_hash),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS journal_catch_up_receipts (receipt_hash text PRIMARY KEY CHECK(receipt_hash ~ '^[a-f0-9]{64}$'),scope_hash text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS journal_commit_receipts (receipt_hash text PRIMARY KEY CHECK(receipt_hash ~ '^[a-f0-9]{64}$'),scope_hash text NOT NULL,idempotency_key text NOT NULL,request_hash text NOT NULL,manifest_hash text NOT NULL REFERENCES journal_input_manifests(manifest_hash),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(scope_hash,idempotency_key));
CREATE TABLE IF NOT EXISTS journal_test_center_bundles (run_id text PRIMARY KEY REFERENCES agent_test_center_runs(run_id),manifest_hash text NOT NULL REFERENCES journal_input_manifests(manifest_hash),check_hash text NOT NULL REFERENCES journal_conservation_checks(check_hash),receipt_hash text NOT NULL REFERENCES journal_commit_receipts(receipt_hash),created_at timestamptz NOT NULL DEFAULT now());
DO $$ DECLARE item text; BEGIN FOREACH item IN ARRAY ARRAY['journal_asset_units','journal_accounts','journal_source_events','journal_input_manifests','journal_transaction_attempts','journal_transactions','journal_postings','journal_lifecycle_events','journal_settlement_links','journal_correction_links','journal_conservation_checks','journal_catch_up_receipts','journal_commit_receipts','journal_test_center_bundles'] LOOP EXECUTE format('DROP TRIGGER IF EXISTS %I_immutable ON %I', item,item); EXECUTE format('CREATE TRIGGER %I_immutable BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION asset_journal_reject_mutation()', item,item); END LOOP; END $$;
COMMIT;
